anchor_month_base as (
    select
        substr(dt, 1, 7) as month_key,
        r_category,
        anchor_id,
        max_by(r_owner, dt) as anchor_name,
        count(distinct dt) as observed_days,
        count(distinct case when valid_acu > 0 then dt end) as valid_acu_days,
        avg(case when valid_acu > 0 then valid_acu end) as avg_daily_acu,
        avg(case when valid_acu > 0 then danmu_ucnt end) as avg_daily_danmu_users,
        sum(case when valid_acu > 0 then danmu_cnt else 0.0 end) as total_danmu_cnt
    from douyu_anchor_day
    group by substr(dt, 1, 7), r_category, anchor_id
    having count(distinct case when valid_acu > 0 then dt end) > 0
),

anchor_month as (
    select
        *,
        date_diff('month', date '2020-01-01', date(concat(month_key, '-01'))) as month_index
    from anchor_month_base
),

next_valid_index as (
    select
        a.r_category,
        a.anchor_id,
        a.month_index,
        min(case when f.valid_acu_days >= 3 then f.month_index end) as next_valid_month_index
    from anchor_month a
    left join anchor_month f
        on a.r_category = f.r_category
       and a.anchor_id = f.anchor_id
       and f.month_index > a.month_index
    group by a.r_category, a.anchor_id, a.month_index
),

anchor_month_next as (
    select
        a.*,
        n.next_valid_month_index,
        f.month_key as next_valid_month_key,
        f.valid_acu_days as next_valid_acu_days
    from anchor_month a
    left join next_valid_index n
        on a.r_category = n.r_category
       and a.anchor_id = n.anchor_id
       and a.month_index = n.month_index
    left join anchor_month f
        on a.r_category = f.r_category
       and a.anchor_id = f.anchor_id
       and n.next_valid_month_index = f.month_index
),

